package tr.gov.kocaeli.sehir.common.config;
import com.github.benmanes.caffeine.cache.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.http.MediaType;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.time.*;import java.util.concurrent.TimeUnit;import java.util.concurrent.atomic.AtomicInteger;
@Component public class RateLimitFilter extends OncePerRequestFilter{private final Cache<String,AtomicInteger>counts=Caffeine.newBuilder().expireAfterWrite(2,TimeUnit.MINUTES).maximumSize(20_000).build();@Override protected boolean shouldNotFilter(HttpServletRequest r){return!r.getRequestURI().startsWith("/api/");}@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String forwarded=req.getHeader("X-Forwarded-For");String ip=forwarded==null?req.getRemoteAddr():forwarded.split(",")[0].trim();String key=ip+":"+Instant.now().getEpochSecond()/60;if(counts.get(key,k->new AtomicInteger()).incrementAndGet()>120){res.setStatus(429);res.setContentType(MediaType.APPLICATION_JSON_VALUE);res.getWriter().write("{\"code\":\"RATE_LIMITED\",\"message\":\"Çok fazla istek gönderildi\",\"fieldErrors\":[]}");return;}chain.doFilter(req,res);}}

